indicator("Independent variance holdout", mode="incremental")


def on_bar(ctx, bar):
    for profile, series in INPUTS.items():
        value = series[ctx.bar_index % 64]
        for period in (2, 3, 7):
            for biased, label in ((True, "biased"), (False, "sample")):
                title = f"Variance {label} {profile} {period}"
                output = ctx.ta.variance(title, period, biased=biased).update(value)
                ctx.plot(title, output)
                title = f"Stdev {label} {profile} {period}"
                if biased:
                    output = ctx.ta.stdev(title, period).update(value)
                else:
                    # Explicit composition, not a direct stdev biased=False API.
                    variance = ctx.ta.variance(title, period, biased=False).update(value)
                    output = None if variance is None else math.sqrt(variance)
                ctx.plot(title, output)
